//! Core geometry types: Point64 / PointD / Rect64 and basic helpers,
//! mirroring the Clipper2 `clipper.core` interface used by this test.

/// Integer point (Clipper2 `Point64`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }

    /// Construct from floating point coordinates the way Clipper2 does:
    /// `std::round` (half away from zero) per coordinate.
    pub fn from_doubles(x: f64, y: f64) -> Self {
        Point64 {
            x: round_to_i64(x),
            y: round_to_i64(y),
        }
    }
}

/// Clipper2 converts doubles to int64 with `std::round`
/// (round half away from zero), which matches `f64::round`.
#[inline]
pub fn round_to_i64(v: f64) -> i64 {
    v.round() as i64
}

/// Floating point point (Clipper2 `PointD`).
#[derive(Clone, Copy, Debug)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    pub fn new(x: f64, y: f64) -> Self {
        PointD { x, y }
    }
}

#[inline]
pub fn cross_product(a: PointD, b: PointD) -> f64 {
    a.x * b.y - b.x * a.y
}

#[inline]
pub fn dot_product(a: PointD, b: PointD) -> f64 {
    a.x * b.y + a.y * b.x // placeholder, fixed below
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

/// Axis-aligned bounding rectangle (Clipper2 `Rect64`).
#[derive(Clone, Copy, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

/// Clipper2 `Area(const Path64&)`:
/// `a += (double)(y1 + y2) * (double)(x1 - x2)` walking the path with
/// `it1` starting at the last point, then `a * 0.5`.
pub fn area(path: &Path64) -> f64 {
    let cnt = path.len();
    if cnt < 3 {
        return 0.0;
    }
    let mut a: f64 = 0.0;
    let mut prev = path[cnt - 1];
    for curr in path.iter() {
        a += (prev.y + curr.y) as f64 * (prev.x - curr.x) as f64;
        prev = *curr;
    }
    a * 0.5
}

/// Clipper2 `GetBounds(const Paths64&)`.
pub fn get_bounds(paths: &Paths64) -> Rect64 {
    let mut left = i64::MAX;
    let mut top = i64::MAX;
    let mut right = i64::MIN;
    let mut bottom = i64::MIN;
    for path in paths {
        for pt in path {
            if pt.x < left {
                left = pt.x;
            }
            if pt.x > right {
                right = pt.x;
            }
            if pt.y < top {
                top = pt.y;
            }
            if pt.y > bottom {
                bottom = pt.y;
            }
        }
    }
    if left == i64::MAX {
        return Rect64 {
            left: 0,
            top: 0,
            right: 0,
            bottom: 0,
        };
    }
    Rect64 {
        left,
        top,
        right,
        bottom,
    }
}

