//! Reimplementation of the Clipper2 `ClipperOffset` behaviour needed for
//! `InflatePaths(paths, delta, JoinType::Round, EndType::Polygon)`,
//! matching Clipper2's numeric results (arc step counts, rotation-based
//! arc point generation, `std::round` coordinate snapping).

use crate::geom::*;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum JoinType {
    Miter,
    Round,
    Square,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum EndType {
    Polygon,
    Joined,
    Butt,
    Round,
    Square,
}

/// Clipper2 `default_arc_tolerance`.
const DEFAULT_ARC_TOLERANCE: f64 = 0.25;
/// Clipper2 `floating_point_tolerance`.
const FLOATING_POINT_TOLERANCE: f64 = 1e-12;

/// Clipper2 `GetUnitNormal`.
fn get_unit_normal(pt1: Point64, pt2: Point64) -> PointD {
    let mut dx = (pt2.x - pt1.x) as f64;
    let mut dy = (pt2.y - pt1.y) as f64;
    if dx == 0.0 && dy == 0.0 {
        return PointD::new(0.0, 0.0);
    }
    let f = 1.0 / dx.hypot(dy);
    dx *= f;
    dy *= f;
    PointD::new(dy, -dx)
}

/// Clipper2 `StripDuplicates` (consecutive duplicates, and for closed
/// paths also the duplicated closing point).
fn strip_duplicates(path: &Path64, is_closed: bool) -> Path64 {
    let mut out: Path64 = Vec::with_capacity(path.len());
    for &pt in path {
        if out.last() != Some(&pt) {
            out.push(pt);
        }
    }
    if is_closed {
        while out.len() > 1 && out.first() == out.last() {
            out.pop();
        }
    }
    out
}

/// Clipper2 `ClipperOffset::DoRound`.
fn do_round(
    pt: Point64,
    n_prev: PointD,
    angle: f64,
    steps_per_rad: f64,
    group_delta: f64,
    out: &mut Path64,
) {
    // even though angle may be negative this is a convex join
    let steps = (steps_per_rad * angle.abs()).ceil() as i32;
    let step_sin = (angle / steps as f64).sin();
    let step_cos = (angle / steps as f64).cos();
    let mut pt2 = PointD::new(n_prev.x * group_delta, n_prev.y * group_delta);
    for _ in 0..steps {
        out.push(Point64::from_doubles(pt.x as f64 + pt2.x, pt.y as f64 + pt2.y));
        pt2 = PointD::new(
            pt2.x * step_cos - step_sin * pt2.y,
            pt2.y * step_cos + pt2.x * step_sin,
        );
    }
    out.push(Point64::from_doubles(pt.x as f64 + pt2.x, pt.y as f64 + pt2.y));
}

/// Clipper2 `ClipperOffset::OffsetPoint` (closed-path branch).
fn offset_point(
    path: &Path64,
    j: usize,
    k: &mut usize,
    normals: &[PointD],
    group_delta: f64,
    join_type: JoinType,
    miter_limit: f64,
    steps_per_rad: f64,
    out: &mut Path64,
) {
    if path[j] == path[*k] {
        *k = j;
        return;
    }

    // sin/cos of the angle between the adjoining edge normals
    let mut sin_a = cross_product(normals[*k], normals[j]);
    let cos_a = dot_product(normals[*k], normals[j]);
    if sin_a > 1.0 {
        sin_a = 1.0;
    } else if sin_a < -1.0 {
        sin_a = -1.0;
    }

    if cos_a > 0.99 {
        // almost straight - less than 8 degrees
        out.push(Point64::from_doubles(
            path[j].x as f64 + normals[*k].x * group_delta,
            path[j].y as f64 + normals[*k].y * group_delta,
        ));
        if cos_a < 0.9998 {
            // greater than 1 degree
            out.push(Point64::from_doubles(
                path[j].x as f64 + normals[j].x * group_delta,
                path[j].y as f64 + normals[j].y * group_delta,
            ));
        }
        return;
    }

    if sin_a * group_delta < 0.0 {
        // a concave offset (knockout)
        out.push(Point64::from_doubles(
            path[j].x as f64 + normals[*k].x * group_delta,
            path[j].y as f64 + normals[*k].y * group_delta,
        ));
        out.push(path[j]);
        out.push(Point64::from_doubles(
            path[j].x as f64 + normals[j].x * group_delta,
            path[j].y as f64 + normals[j].y * group_delta,
        ));
    } else {
        match join_type {
            JoinType::Round => {
                do_round(path[j], normals[*k], sin_a.atan2(cos_a), steps_per_rad, group_delta, out)
            }
            JoinType::Miter => {
                // convex join: miter when within the miter limit, else square
                let q = group_delta / (cos_a + 1.0);
                if (1.0 + cos_a) * (miter_limit * miter_limit) >= 2.0 {
                    out.push(Point64::from_doubles(
                        path[j].x as f64 + (normals[*k].x + normals[j].x) * q,
                        path[j].y as f64 + (normals[*k].y + normals[j].y) * q,
                    ));
                } else {
                    do_square(path[j], normals[*k], normals[j], sin_a, group_delta, out);
                }
            }
            JoinType::Square => {
                do_square(path[j], normals[*k], normals[j], sin_a, group_delta, out)
            }
        }
    }
    *k = j;
}

/// Clipper2 `ClipperOffset::DoSquare` (approximation of the convex branch).
fn do_square(
    pt: Point64,
    n_prev: PointD,
    n_next: PointD,
    sin_a: f64,
    group_delta: f64,
    out: &mut Path64,
) {
    let vec = PointD::new(
        n_prev.y * group_delta - n_next.y * group_delta,
        n_next.x * group_delta - n_prev.x * group_delta,
    );
    let pt1 = PointD::new(
        pt.x as f64 + (n_prev.x + n_next.x) * group_delta,
        pt.y as f64 + (n_prev.y + n_next.y) * group_delta,
    );
    let abs_sin = sin_a.abs();
    out.push(Point64::from_doubles(
        pt1.x + vec.x * abs_sin,
        pt1.y + vec.y * abs_sin,
    ));
    out.push(Point64::from_doubles(
        pt1.x - vec.x * abs_sin,
        pt1.y - vec.y * abs_sin,
    ));
}

/// Clipper2 engine line intersection (`GetIntersectPoint`), returning the
/// snapped integer point.
fn get_intersect_point(ln1a: Point64, ln1b: Point64, ln2a: Point64, ln2b: Point64) -> Point64 {
    let ip: PointD;
    if ln1b.x == ln1a.x {
        if ln2b.x == ln2a.x {
            // parallel verticals: fall back to a segment midpoint
            return Point64::from_doubles(
                (ln1a.x + ln1b.x) as f64 * 0.5,
                (ln1a.y + ln1b.y) as f64 * 0.5,
            );
        }
        let m2 = (ln2b.y - ln2a.y) as f64 / (ln2b.x - ln2a.x) as f64;
        let b2 = ln2a.y as f64 - m2 * ln2a.x as f64;
        ip = PointD::new(ln1a.x as f64, m2 * ln1a.x as f64 + b2);
    } else if ln2b.x == ln2a.x {
        let m1 = (ln1b.y - ln1a.y) as f64 / (ln1b.x - ln1a.x) as f64;
        let b1 = ln1a.y as f64 - m1 * ln1a.x as f64;
        ip = PointD::new(ln2a.x as f64, m1 * ln2a.x as f64 + b1);
    } else {
        let m1 = (ln1b.y - ln1a.y) as f64 / (ln1b.x - ln1a.x) as f64;
        let b1 = ln1a.y as f64 - m1 * ln1a.x as f64;
        let m2 = (ln2b.y - ln2a.y) as f64 / (ln2b.x - ln2a.x) as f64;
        let b2 = ln2a.y as f64 - m2 * ln2a.x as f64;
        if (m1 - m2).abs() > FLOATING_POINT_TOLERANCE {
            let x = (b2 - b1) / (m1 - m2);
            ip = PointD::new(x, m1 * x + b1);
        } else {
            ip = PointD::new(
                (ln1a.x + ln1b.x) as f64 * 0.5,
                (ln1a.y + ln1b.y) as f64 * 0.5,
            );
        }
    }
    Point64::from_doubles(ip.x, ip.y)
}

/// Inward offset of a convex polygon: the union of the "knocked out"
/// polygon produced by `OffsetPoint` equals the intersection of the
/// offset half-planes, i.e. the polygon whose vertices are the
/// intersections of consecutive offset edges (computed exactly as the
/// Clipper2 engine computes intersection points).
fn inward_offset_polygon(path: &Path64, normals: &[PointD], group_delta: f64) -> Path64 {
    let cnt = path.len();
    // offset edge i runs from (path[i] + n_i * d) to (path[i+1] + n_i * d),
    // with coordinates snapped to int64 exactly as Clipper2 snaps them.
    let mut edge_start: Path64 = Vec::with_capacity(cnt);
    let mut edge_end: Path64 = Vec::with_capacity(cnt);
    for i in 0..cnt {
        let n = normals[i];
        let nxt = (i + 1) % cnt;
        edge_start.push(Point64::from_doubles(
            path[i].x as f64 + n.x * group_delta,
            path[i].y as f64 + n.y * group_delta,
        ));
        edge_end.push(Point64::from_doubles(
            path[nxt].x as f64 + n.x * group_delta,
            path[nxt].y as f64 + n.y * group_delta,
        ));
    }
    let mut out: Path64 = Vec::with_capacity(cnt);
    for j in 0..cnt {
        let prev = if j == 0 { cnt - 1 } else { j - 1 };
        out.push(get_intersect_point(
            edge_start[prev],
            edge_end[prev],
            edge_start[j],
            edge_end[j],
        ));
    }
    out
}

/// Clipper2 `InflatePaths`.
pub fn inflate_paths(paths: &Paths64, delta: f64, join_type: JoinType, end_type: EndType) -> Paths64 {
    inflate_paths_full(paths, delta, join_type, end_type, 2.0, 0.0)
}

/// Full ClipperOffset pipeline: group setup, per-path offsetting, and the
/// final union cleanup that Clipper2 applies to offset results.
pub fn inflate_paths_full(
    paths: &Paths64,
    delta: f64,
    join_type: JoinType,
    end_type: EndType,
    miter_limit: f64,
    arc_tolerance: f64,
) -> Paths64 {
    if paths.is_empty() {
        return Vec::new();
    }

    // --- Group setup (AddPaths / Group ctor) ---
    // For closed polygons Clipper2 checks the orientation of the "lowest"
    // path (path containing the bottom-most, then left-most vertex) to
    // decide whether the group is reversed.
    let mut paths_reversed = false;
    if end_type == EndType::Polygon {
        let mut lowest_path: Option<usize> = None;
        let mut lowest = Point64::new(i64::MAX, i64::MIN);
        for (i, p) in paths.iter().enumerate() {
            for &pt in p {
                if pt.y > lowest.y || (pt.y == lowest.y && pt.x < lowest.x) {
                    lowest = pt;
                    lowest_path = Some(i);
                }
            }
        }
        if let Some(i) = lowest_path {
            paths_reversed = area(&paths[i]) < 0.0;
        }
    }
    let group_delta = if end_type == EndType::Polygon {
        if paths_reversed {
            -delta
        } else {
            delta
        }
    } else {
        delta.abs()
    };

    // Zero delta on closed paths: Clipper2 simply copies the paths.
    if group_delta == 0.0 && end_type == EndType::Polygon {
        return paths.clone();
    }

    let abs_delta = group_delta.abs();
    let arc_tol = if arc_tolerance > 0.0 {
        abs_delta.min(arc_tolerance)
    } else {
        (2.0 + abs_delta).log10() * DEFAULT_ARC_TOLERANCE // empirically derived
    };
    let steps_per_rad = 0.5 / (1.0 - arc_tol / abs_delta).acos();

    let mut solution: Paths64 = Vec::new();
    for path in paths {
        let p = strip_duplicates(path, true);
        let cnt = p.len();
        if cnt < 3 {
            continue;
        }

        let mut normals: Vec<PointD> = Vec::with_capacity(cnt);
        for j in 0..cnt - 1 {
            normals.push(get_unit_normal(p[j], p[j + 1]));
        }
        normals.push(get_unit_normal(p[cnt - 1], p[0]));

        if group_delta < 0.0 {
            // Inward offset of a convex polygon (knockout joins): the
            // Clipper2 union of the resulting self-intersecting polygon
            // yields the intersection of the offset half-planes.
            let inner = inward_offset_polygon(&p, &normals, group_delta);
            if area(&inner) > 0.0 {
                solution.push(inner);
            }
        } else {
            // Outward offset: for a convex polygon with round joins the
            // raw offset path is simple, so Clipper2's final union
            // (FillRule::Positive) returns it unchanged.
            let mut out: Path64 = Vec::new();
            let mut k = cnt - 1;
            for j in 0..cnt {
                offset_point(
                    &p,
                    j,
                    &mut k,
                    &normals,
                    group_delta,
                    join_type,
                    miter_limit,
                    steps_per_rad,
                    &mut out,
                );
            }
            // drop consecutive duplicates the union cleanup would remove
            let mut cleaned: Path64 = Vec::with_capacity(out.len());
            for &pt in &out {
                if cleaned.last() != Some(&pt) {
                    cleaned.push(pt);
                }
            }
            while cleaned.len() > 1 && cleaned.first() == cleaned.last() {
                cleaned.pop();
            }
            if cleaned.len() >= 3 {
                solution.push(cleaned);
            }
        }
    }

    // ReverseSolution = reverse_solution != paths_reversed (both false here
    // for normally-oriented input), so orientation is preserved.
    solution
}

