    for &pt in &output {
        if cleaned.last() != Some(&pt) {
            cleaned.push(pt);
        }
    }
    while cleaned.len() > 1 && cleaned.first() == cleaned.last() {
        cleaned.pop();
    }
    if cleaned.len() < 3 {
        return Vec::new();
    }
    cleaned
}

/// Clipper2 `Intersect(subjects, clips, fillrule)` restricted to convex
/// clip paths (sufficient for this test's inputs).
pub fn intersect(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
    let mut result: Paths64 = Vec::new();
    for subject in subjects {
        let mut pieces: Paths64 = vec![subject.clone()];
        for clip in clips {
            let mut next: Paths64 = Vec::new();
            for piece in &pieces {
                let clipped = sutherland_hodgman(piece, clip);
                if !clipped.is_empty() {
                    next.push(clipped);
                }
            }
            pieces = next;
        }
        for piece in pieces {
            if area(&piece) != 0.0 {
                result.push(piece);
            }
        }
    }
    // Clipper2's Intersect output keeps a consistent (positive) orientation
    // for the region; normalise so downstream offsetting goes outwards.
    for path in &mut result {
        if area(path) < 0.0 {
            path.reverse();
        }
    }
    result
}

