// probe: compute offset area for the triangle with explicit per-corner step counts
use std::env;

#[derive(Clone, Copy)]
struct P { x: f64, y: f64 }

fn round_i64(v: f64) -> i64 { v.round() as i64 }

fn unit_normal(p1: (i64,i64), p2: (i64,i64)) -> P {
    let mut dx = (p2.0 - p1.0) as f64;
    let mut dy = (p2.1 - p1.1) as f64;
    let f = 1.0 / dx.hypot(dy);
    dx *= f; dy *= f;
    P { x: dy, y: -dx }
}

fn main() {
    let a: Vec<String> = env::args().collect();
    let d: f64 = a[1].parse().unwrap();
    let steps_req: Vec<i64> = a[2..].iter().map(|s| s.parse().unwrap()).collect();

    let path: Vec<(i64,i64)> = vec![(50,0),(100,100),(0,100)];
    let cnt = 3;
    let mut normals = Vec::new();
    for j in 0..cnt-1 { normals.push(unit_normal(path[j], path[j+1])); }
    normals.push(unit_normal(path[cnt-1], path[0]));

    let mut out: Vec<(i64,i64)> = Vec::new();
    let mut k = cnt - 1;
    for j in 0..cnt {
        let sin_a = normals[k].x*normals[j].y - normals[j].x*normals[k].y;
        let cos_a = normals[k].x*normals[j].x + normals[k].y*normals[j].y;
        let angle = sin_a.atan2(cos_a);
        let steps = if steps_req.is_empty() {
            let abs_delta = d.abs();
            let arc_tol = (2.0+abs_delta).log10() * 0.25;
            let steps_per_rad = 0.5 / (1.0 - arc_tol/abs_delta).acos();
            (steps_per_rad * angle.abs()).ceil() as i64
        } else { steps_req[j] };
        let step_sin = (angle / steps as f64).sin();
        let step_cos = (angle / steps as f64).cos();
        let mut pt2 = P { x: normals[k].x * d, y: normals[k].y * d };
        for _ in 0..steps {
            out.push((round_i64(path[j].0 as f64 + pt2.x), round_i64(path[j].1 as f64 + pt2.y)));
            pt2 = P { x: pt2.x*step_cos - step_sin*pt2.y, y: pt2.y*step_cos + pt2.x*step_sin };
        }
        out.push((round_i64(path[j].0 as f64 + pt2.x), round_i64(path[j].1 as f64 + pt2.y)));
        k = j;
    }
    let mut area = 0.0f64;
    let mut prev = out[out.len()-1];
    for &c in &out {
        area += (prev.1 + c.1) as f64 * (prev.0 - c.0) as f64;
        prev = c;
    }
    println!("d={} steps={:?} npts={} area={}", d, steps_req, out.len(), area*0.5);
    if a.last().unwrap() == "v" {
        for p in &out { println!("  {},{}", p.0, p.1); }
    }
}

