struct P { x: f64, y: f64 }
fn unit_normal(p1: (i64,i64), p2: (i64,i64)) -> P {
    let mut dx = (p2.0 - p1.0) as f64;
    let mut dy = (p2.1 - p1.1) as f64;
    let f = 1.0 / dx.hypot(dy);
    dx *= f; dy *= f;
    P { x: dy, y: -dx }
}
fn main() {
    let d = 4.0f64;
    let path: Vec<(i64,i64)> = vec![(50,0),(100,100),(0,100)];
    let cnt = 3;
    let mut normals = Vec::new();
    for j in 0..cnt-1 { normals.push(unit_normal(path[j], path[j+1])); }
    normals.push(unit_normal(path[cnt-1], path[0]));
    for (spr, label) in [(0.5f64/(1.0f64-(2.0f64+d).log10()*0.25/d).acos(), "orig")] {
        println!("spr={} ({})", spr, label);
        let mut k = cnt - 1;
        for j in 0..cnt {
            let sin_a = normals[k].x*normals[j].y - normals[j].x*normals[k].y;
            let cos_a = normals[k].x*normals[j].x + normals[k].y*normals[j].y;
            let angle = sin_a.atan2(cos_a);
            let steps = (spr * angle.abs()).ceil().max(1.0) as i64;
            let step_sin = (angle / steps as f64).sin();
            let step_cos = (angle / steps as f64).cos();
            let mut pt2 = P { x: normals[k].x * d, y: normals[k].y * d };
            println!("vertex {} angle={} steps={}", j, angle, steps);
            for i in 0..=steps {
                let fx = path[j].0 as f64 + pt2.x;
                let fy = path[j].1 as f64 + pt2.y;
                println!("  raw=({:.6},{:.6}) snapped=({},{})", fx, fy, fx.round() as i64, fy.round() as i64);
                pt2 = P { x: pt2.x*step_cos - step_sin*pt2.y, y: pt2.y*step_cos + pt2.x*step_sin };
                let _ = i;
            }
            k = j;
        }
    }
}
