// compare hypot vs sqrt normalisation, print raw arc doubles for d=4
#[derive(Clone, Copy)]
struct P { x: f64, y: f64 }
fn main() {
    let d = 4.0f64;
    let path: Vec<(i64,i64)> = vec![(50,0),(100,100),(0,100)];
    let cnt = 3;
    for mode in ["hypot", "sqrt"] {
        let mut normals = Vec::new();
        for j in 0..cnt {
            let p1 = path[j]; let p2 = path[(j+1)%cnt];
            let mut dx = (p2.0 - p1.0) as f64;
            let mut dy = (p2.1 - p1.1) as f64;
            let len = if mode == "hypot" { dx.hypot(dy) } else { (dx*dx+dy*dy).sqrt() };
            let f = 1.0 / len;
            dx *= f; dy *= f;
            normals.push(P { x: dy, y: -dx });
        }
        println!("mode={} normals={:?}", mode, normals.iter().map(|p| (p.x.to_bits(), p.y.to_bits())).collect::<Vec<_>>());
        let spr = 0.5 / (1.0 - (2.0f64+d).log10()*0.25/d).acos();
        let mut out: Vec<(i64,i64)> = Vec::new();
        let mut k = cnt - 1;
        for j in 0..cnt {
            let sin_a = normals[k].x*normals[j].y - normals[j].x*normals[k].y;
            let cos_a = normals[k].x*normals[j].x + normals[k].y*normals[j].y;
            let angle = sin_a.atan2(cos_a);
            let steps = (spr * angle.abs()).ceil().max(1.0) as i64;
            let step_sin = (angle / steps as f64).sin();
            let step_cos = (angle / steps as f64).cos();
            let mut pt2 = P { x: normals[k].x * d, y: normals[k].y * d };
            for _ in 0..steps {
                out.push(((path[j].0 as f64 + pt2.x).round() as i64, (path[j].1 as f64 + pt2.y).round() as i64));
                pt2 = P { x: pt2.x*step_cos - step_sin*pt2.y, y: pt2.y*step_cos + pt2.x*step_sin };
            }
            out.push(((path[j].0 as f64 + pt2.x).round() as i64, (path[j].1 as f64 + pt2.y).round() as i64));
            k = j;
        }
        let mut area = 0.0f64;
        let mut prev = out[out.len()-1];
        for &c in &out { area += (prev.1 + c.1) as f64 * (prev.0 - c.0) as f64; prev = c; }
        println!("mode={} area={}", mode, area*0.5);
    }
}
