fn main() {
    let poly: Vec<(f64,f64)> = vec![(46.,-2.),(48.,-3.),(50.,-4.),(52.,-3.),(54.,-2.),(104.,98.),(104.,100.),(103.,102.),(102.,103.),(100.,104.),(0.,104.),(-2.,103.),(-3.,102.),(-4.,100.),(-4.,98.)];
    // scanline area of polygon
    let mut area = 0.0f64;
    let n = poly.len();
    let mut y = -4.0f64;
    while y < 104.0 {
        let yc = y + 0.001;
        // find intersections
        let mut xs = Vec::new();
        for i in 0..n {
            let (x1,y1) = poly[i]; let (x2,y2) = poly[(i+1)%n];
            if (y1 <= yc && y2 > yc) || (y2 <= yc && y1 > yc) {
                xs.push(x1 + (yc-y1)*(x2-x1)/(y2-y1));
            }
        }
        xs.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut w = 0.0;
        let mut i = 0;
        while i+1 < xs.len() { w += xs[i+1]-xs[i]; i += 2; }
        area += w * 0.001;
        y += 0.001;
    }
    println!("scanline poly area = {:.2}", area);
    // minkowski area via sampling: triangle + disk r=4
    let tri = [(50.,0.),(100.,100.),(0.,100.)];
    let dist_pt_seg = |px: f64, py: f64, ax: f64, ay: f64, bx: f64, by: f64| -> f64 {
        let dx = bx-ax; let dy = by-ay;
        let t = (((px-ax)*dx + (py-ay)*dy) / (dx*dx+dy*dy)).clamp(0.0, 1.0);
        let cx = ax + t*dx; let cy = ay + t*dy;
        ((px-cx)*(px-cx)+(py-cy)*(py-cy)).sqrt()
    };
    let inside_tri = |px: f64, py: f64| -> bool {
        // barycentric-ish sign checks
        let s = |ax: f64, ay: f64, bx: f64, by: f64| (bx-ax)*(py-ay) - (by-ay)*(px-ax);
        let c0 = s(tri[0].0, tri[0].1, tri[1].0, tri[1].1);
        let c1 = s(tri[1].0, tri[1].1, tri[2].0, tri[2].1);
        let c2 = s(tri[2].0, tri[2].1, tri[0].0, tri[0].1);
        (c0 >= 0.0 && c1 >= 0.0 && c2 >= 0.0) || (c0 <= 0.0 && c1 <= 0.0 && c2 <= 0.0)
    };
    let mut cnt = 0u64; let total = 20_000_000u64;
    let (x0,x1,y0,y1) = (-4.0, 104.0, -4.0, 104.0);
    let mut seed = 12345u64;
    let mut rng = move || { seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407); (seed >> 33) as f64 / (1u64<<31) as f64 };
    for _ in 0..total {
        let px = x0 + rng()*(x1-x0);
        let py = y0 + rng()*(y1-y0);
        let inside = inside_tri(px,py)
            || dist_pt_seg(px,py, tri[0].0,tri[0].1, tri[1].0,tri[1].1) <= 4.0
            || dist_pt_seg(px,py, tri[1].0,tri[1].1, tri[2].0,tri[2].1) <= 4.0
            || dist_pt_seg(px,py, tri[2].0,tri[2].1, tri[0].0,tri[0].1) <= 4.0;
        if inside { cnt += 1; }
    }
    let bbox = (x1-x0)*(y1-y0);
    println!("minkowski area est = {:.2}", cnt as f64 / total as f64 * bbox);
    println!("steiner = {:.2}", 5000.0 + 4.0*(100.0+2.0*12500f64.sqrt()) + 16.0*std::f64::consts::PI);
}
EOF
